package main

import "fmt"

// dedup returns a new slice containing only the first occurrence
// of each string in the input slice, preserving the original order.
func dedup(items []string) []string {
	seen := make(map[string]bool)
	result := make([]string, 0, len(items))
	for _, item := range items {
		if !seen[item] {
			seen[item] = true
			result = append(result, item)
		}
	}
	return result
}

func main() {
	// Example: dedup([]string{"a", "b", "a", "c", "b"}) -> ["a" "b" "c"]
	input := []string{"a", "b", "a", "c", "b"}
	fmt.Println(dedup(input))
}
