// DeduplicateStringsInPlace removes duplicate strings from the slice in-place,
// preserving the order of first occurrence. Returns the deduplicated slice.
func DeduplicateStringsInPlace(input []string) []string {
	seen := make(map[string]bool)
	writeIdx := 0

	for _, str := range input {
		if !seen[str] {
			seen[str] = true
			input[writeIdx] = str
			writeIdx++
		}
	}

	return input[:writeIdx]
}
